param([int]$Port=8787)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $MyInvocation.MyCommand.Path;$http=[Net.HttpListener]::new();$http.Prefixes.Add("http://localhost:$Port/");$http.Start();$url="http://localhost:$Port/";Write-Host "Digital Hub: $url" -ForegroundColor Green;Write-Host 'Press Ctrl+C to stop.';Start-Process $url;$types=@{'.html'='text/html; charset=utf-8';'.png'='image/png'};$logo='C:\Users\KhaingZawShein\Downloads\New folder\digital-it-hub-main\digital-it-hub-main\logo.png'
try{while($http.IsListening){$c=$http.GetContext();$p=[Uri]::UnescapeDataString($c.Request.Url.AbsolutePath.TrimStart('/'));if(!$p){$p='index.html'};if($p -in @('dashbaord','dashboard','manpower','Expenes','expenses','microsoft-365')){$p='index.html'};$f=if($p-eq'logo.png' -and !(Test-Path (Join-Path $root 'logo.png'))){$logo}else{[IO.Path]::GetFullPath((Join-Path $root $p))};if(($f.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)-or$f-eq$logo)-and(Test-Path $f -PathType Leaf)){$b=[IO.File]::ReadAllBytes($f);$c.Response.ContentType=$types[[IO.Path]::GetExtension($f).ToLower()];$c.Response.Headers.Add('Cache-Control','no-store, no-cache, must-revalidate');$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length)}else{$c.Response.StatusCode=404};$c.Response.Close()}}finally{$http.Stop();$http.Close()}
